package org.concordia.babycdf;
import com.fasterxml.jackson.databind.node.*;import java.util.*;import java.io.IOException;import java.nio.charset.*;
/** Read-only exact-agenda evaluation. */
public final class AgendaFollowingReview {
 private final Advisory.Api api;private final Map<String,EvidenceBundle> cache=new HashMap<>();private final SupplementalAssessment supplemental;
 public AgendaFollowingReview(Advisory.Api api){this(api,null);}
 public AgendaFollowingReview(Advisory.Api api,SupplementalAssessment supplemental){this.api=api;this.supplemental=supplemental;}
 public ObjectNode cycle(Reviewer.LedgerRuleGateway ledger)throws Exception {
  var result=Advisory.JSON.createObjectNode();var reviews=result.putArray("reviews");result.putArray("errors");result.put("ledger_submission","none: read-only integrated agenda following");
  var agendas=new ArrayList<IntegratedAgendaSnapshot>();for(var event:ledger.agendaEvents()){var decoded=IntegratedAgendaSnapshot.decode(event);if(decoded!=null)agendas.add(decoded);}
  if(agendas.isEmpty())return result.put("status","IDLE").put("reason","no Concordia source agenda pending");
  if(agendas.size()!=1)throw new IOException("ambiguous pending Concordia source agendas");var agenda=agendas.getFirst();var rules=ledger.activeRules();if(rules.stream().filter(r->r!=null&&"architecture-review".equals(r.ruleId())).count()!=1)throw new IOException("ambiguous ACTIVE rule selection");var rule=Reviewer.select(rules);
  RuleDocument.announceActive(rule,System.err);
  result.put("rule_version",rule.version()).put("rule_contract_id",rule.contractId()).put("rule_id",rule.ruleId()).put("rule_document_sha256",rule.ruleRef()==null?"":rule.ruleRef().sha256()).put("rule_ref",rule.ruleRef()==null?"":rule.ruleRef().location()).put("status","evaluated");var item=reviews.addObject().put("number",agenda.number()).put("round_id",agenda.round()).put("url",agenda.url()).put("revision",agenda.fingerprint()).put("rule_version_evaluated",rule.version()).put("rule_contract_id",rule.contractId());var findings=item.putArray("findings");
  if(agenda.blocked()||rule.ruleFailure()!=null){item.put("pinned",false).put("status","INCONCLUSIVE");findings.addObject().put("status","insufficient_evidence").put("detail","blocked/unknown immutable evidence or rule");return result;}
  String key=agenda.delivery()==null?agenda.head()+":"+agenda.files():agenda.delivery().toString();EvidenceBundle bundle=cache.get(key);
  if(bundle==null){String selectedHead=agenda.delivery()==null?agenda.head():agenda.delivery().commit();var selectedFiles=new ArrayList<>(agenda.files());
   if(agenda.delivery()!=null){var commit=api.get("repos/"+ConcordiaDemoScope.REPO+"/commits/"+selectedHead);if(!commit.path("sha").asText().equals(selectedHead))throw new IOException("delivery commit mismatch");var declaredTime=commit.path("commit").path("committer").path("date").asText();if(declaredTime.isEmpty()||java.time.Instant.parse(declaredTime).isAfter(agenda.delivery().triggerAt()))throw new IOException("delivery commit after trigger");var treeEvidence=api.get("repos/"+ConcordiaDemoScope.REPO+"/git/trees/"+selectedHead+"?recursive=1");if(treeEvidence.path("truncated").asBoolean(true))throw new IOException("delivery tree incomplete");for(var node:treeEvidence.path("tree"))if(node.path("type").asText().equals("blob")&&node.path("path").asText().matches("(?:proposals|rfps|daml|docs)/.*\\.(?:md|daml)"))selectedFiles.add(new IntegratedAgendaSnapshot.File(node.path("path").asText(),node.path("sha").asText()));if(selectedFiles.isEmpty())throw new IOException("no bounded delivery evidence");}
   var tree=api.get("repos/"+ConcordiaDemoScope.REPO+"/git/trees/"+selectedHead+"?recursive=1");if(tree.path("truncated").asBoolean(true))throw new IOException("incomplete pinned tree");var offered=new ArrayList<EvidenceBundle.File>();var expected=new HashSet<String>();int total=0;
   for(var file:selectedFiles){boolean member=false;for(var node:tree.path("tree"))if(node.path("path").asText().equals(file.path())&&node.path("sha").asText().equals(file.blob())&&node.path("type").asText().equals("blob"))member=true;if(!member)throw new IOException("pin not in immutable head tree");var blob=api.get("repos/"+ConcordiaDemoScope.REPO+"/git/blobs/"+file.blob());if(!blob.path("encoding").asText().equals("base64")||blob.path("truncated").asBoolean())throw new IOException("invalid pinned blob encoding");byte[] bytes=Base64.getMimeDecoder().decode(blob.path("content").asText());total+=bytes.length;if(total>EvidenceBundle.MAX_EVIDENCE_BYTES)throw new IOException("immutable evidence bound");String text=StandardCharsets.UTF_8.newDecoder().decode(java.nio.ByteBuffer.wrap(bytes)).toString();if(text.indexOf('\0')>=0)throw new IOException("binary immutable evidence");if(!EvidenceBundle.blob(text).equals(file.blob()))throw new IOException("immutable blob digest mismatch");offered.add(new EvidenceBundle.File(file.path(),file.blob(),bytes.length,text));expected.add(file.path());}
   bundle=EvidenceBundle.proposal(agenda.url(),selectedHead,offered,expected,true);if(!bundle.completeness()||!bundle.verified(selectedHead))throw new IOException("immutable evidence bundle mismatch");if(cache.size()<64)cache.put(key,bundle);
  }
  item.put("kind",agenda.delivery()==null?"proposal_pr":"milestone_issue").put("pinned",true).put("supplemental_valid",true).put("head_commit",bundle.headSha()).put("body_sha256",agenda.digest()).put("rule_document_sha256",rule.ruleRef()==null?"":rule.ruleRef().sha256()).put("evidence_identity",bundle.cacheIdentity());item.set("evidence_bundle",Advisory.JSON.valueToTree(bundle));boolean proposalAbsenceEligible=agenda.delivery()==null&&bundle.completeness()&&bundle.verified(agenda.head());item.put("head_consistent",proposalAbsenceEligible).put("absence_eligible",proposalAbsenceEligible).put("immutable_snapshot_verified",true).put("complete",bundle.completeness());for(var clause:rule.clauses())findings.add(clause.requiredPhrases().isEmpty()&&clause.forbiddenPhrases().isEmpty()&&!"PRESENCE_REQUIRED".equals(clause.kind())?Advisory.finding(bundle.evidenceText(),true,clause):ClauseCheck.evaluate(clause,bundle.evidenceText(),true,bundle,proposalAbsenceEligible));
  if(supplemental!=null){item.put("_supplemental_text",bundle.evidenceText());supplemental.assessCycle(reviews,rule,"review-proposal-or-milestone","ledger_effective_rule");}else Advisory.stripBundleContents(item);return result;
 }
}
